-- Gerado por scripts/sql/wit2-virada.ts (não editar à mão): a virada no servidor dá o mesmo que src/game/migration.ts.
\set ON_ERROR_STOP on
SELECT set_config('test.uid', '', false);
SELECT set_config('test.email', 'ninguem@exemplo.com', false);
DO $$ BEGIN PERFORM wit2_migrate_student('dddddddd-0000-0000-0000-000000000001'); RAISE EXCEPTION 'devia recusar'; EXCEPTION WHEN insufficient_privilege THEN NULL; END $$;
SELECT set_config('test.email', 'master@exemplo.com', false);
SELECT (wit2_migrate_status()->>'migrados')::int = 0 AND (wit2_migrate_status()->>'teste')::int >= 1 AS "status antes da virada";
CREATE TEMP TABLE rep AS SELECT wit2_migrate_student('dddddddd-0000-0000-0000-000000000001') AS j;
SELECT (j->>'cards')::int = 3 AND (j->>'coins')::int = 500 AND (j->>'talentPoints')::int = 3 AND j->>'path' = 'desafiante' FROM rep;
SELECT j->'packs' = '{"comum":6,"raro":2,"epico":1}'::jsonb AND j->'dust' = '{"rare":50,"common":13}'::jsonb FROM rep;
SELECT (SELECT coalesce(jsonb_agg(v ORDER BY v), '[]'::jsonb) FROM jsonb_array_elements_text(j->'titles') v) = '["ajudante-semana","guardiao-presenca","veterano"]'::jsonb AND (SELECT coalesce(jsonb_agg(v ORDER BY v), '[]'::jsonb) FROM jsonb_array_elements_text(j->'unknownItems') v) = '["Espada que sumiu"]'::jsonb FROM rep;
SELECT (SELECT qty FROM wit2_cards WHERE student_id = 'dddddddd-0000-0000-0000-000000000001' AND card_id = 'manto-da-aurora') = 1 AS "carta manto-da-aurora";
SELECT (SELECT qty FROM wit2_cards WHERE student_id = 'dddddddd-0000-0000-0000-000000000001' AND card_id = 'furia-berserker') = 1 AS "carta furia-berserker";
SELECT (SELECT qty FROM wit2_cards WHERE student_id = 'dddddddd-0000-0000-0000-000000000001' AND card_id = 'golpe-conquistador') = 1 AS "carta golpe-conquistador";
SELECT (SELECT coins FROM wit2_wallet WHERE student_id = 'dddddddd-0000-0000-0000-000000000001') = 500 AS "moedas na carteira";
SELECT (SELECT qty FROM wit2_packs WHERE student_id = 'dddddddd-0000-0000-0000-000000000001' AND pack_id = 'comum') = 6 AS "pacote comum";
SELECT (SELECT qty FROM wit2_packs WHERE student_id = 'dddddddd-0000-0000-0000-000000000001' AND pack_id = 'raro') = 2 AS "pacote raro";
SELECT (SELECT qty FROM wit2_packs WHERE student_id = 'dddddddd-0000-0000-0000-000000000001' AND pack_id = 'epico') = 1 AS "pacote epico";
SELECT (SELECT data->'legado'->>'nivel' FROM wit2_progress WHERE student_id = 'dddddddd-0000-0000-0000-000000000001')::int = 32 AND (SELECT data->>'caminhoSugerido' FROM wit2_progress WHERE student_id = 'dddddddd-0000-0000-0000-000000000001') = 'desafiante' AS "legado no progresso";
SELECT (wit2_migrate_student('dddddddd-0000-0000-0000-000000000001')->>'ja')::boolean AS "rodar de novo não dá de novo";
SELECT (SELECT coins FROM wit2_wallet WHERE student_id = 'dddddddd-0000-0000-0000-000000000001') = 500 AS "moedas não dobraram";
SELECT (wit2_migrate_all()->>'migrados')::int >= 2 AS "migra os que faltam";
SELECT NOT EXISTS (SELECT 1 FROM wit2_legacy WHERE student_id = 'dddddddd-0000-0000-0000-000000000002') AS "conta de teste fica de fora";
SELECT (report->>'coins')::int = 50 AND (report->>'talentPoints')::int = 0 AND report->>'path' = 'desafiante' AND report->'packs' = '{}'::jsonb AND report->'dust' = '{}'::jsonb FROM wit2_legacy WHERE student_id = 'dddddddd-0000-0000-0000-000000000003';
SELECT (report->>'coins')::int = 60 AND (report->>'talentPoints')::int = 6 AND report->>'path' = 'guardiao' AND report->'packs' = '{"comum":3,"raro":1}'::jsonb AND report->'dust' = '{"epic":30}'::jsonb FROM wit2_legacy WHERE student_id = 'dddddddd-0000-0000-0000-000000000004';
SELECT (wit2_migrate_all()->>'migrados')::int = 0 AS "segunda vez: ninguém";
SELECT set_config('test.email', '', false);
